package com.dronelink.app.video

/**
 * RFC 2435 RTP JPEG depacketizer.
 *
 * Every RTP payload for MJPEG over RTP starts with an 8-byte main JPEG header:
 *   Type-specific(1) | Fragment Offset(3, big-endian) | Type(1) |
 *   Q(1) | Width(1) | Height(1)
 * followed — on EVERY fragment when the Type field has bit 0x40 set — by a
 *   4-byte Restart Marker header (Restart Interval(16, big-endian) |
 *   F(1) | L(1) | Restart Count(14)), and on the first fragment of a frame
 *   only (fragment offset 0) — when Q >= 128 — by a 4-byte Quantization
 *   Table header (MBZ | Precision | Length(16, big-endian)), plus `Length`
 *   bytes of quantization table data when Length > 0,
 * and then the JPEG payload fragment (entropy-coded scan data).
 *
 * RFC 2435 represents JPEG in abbreviated form: the frame and scan headers
 * (SOI/APP0/DQT/DHT/SOF0/SOS) are NOT transmitted — they are inferred from the
 * RTP/JPEG header fields.
 *
 * The camera that this project targets (a CooingDV BL60x-class toy FPV quad)
 * does NOT emit a conforming RFC 2435 stream: its entropy is coded with the
 * vendor's own (near-standard) Huffman DC tables and 4:4:4 sampling, and the
 * vendor's Android app assembles frames by prepending one of six fixed JPEG
 * interchange headers (640x360, Q5/10/25/50/75/100) extracted from the
 * official RC FPV app's `libuav_tc.so`. Decoding the camera's entropy with
 * standard Annex K tables + 4:2:0 sampling fails at the first DC symbol, which
 * produced the earlier black/garbage frames. We therefore emit the matching
 * vendor header template chosen by quality, and prepend it to the reassembled
 * scan — verified to decode with ffmpeg (640x360 baseline JPEG).
 *
 * Reassembly: place each fragment at its byte offset into a frame buffer —
 * never concatenate payloads (the 8-byte headers would interleave with JPEG
 * data and corrupt the frame), never rescan for SOI/EOI. Emit the complete
 * JPEG only when the RTP MARKER bit arrives (final fragment of the frame).
 */
class Rfc2435Reassembler(
    private val onFrame: (frame: ByteArray) -> Unit,
) {
    @Volatile
    var frames = 0
        private set

    private var frameBuf = ByteArray(0)
    private var written = 0
    private var header: ByteArray? = null
    private var sawStart = false

    /**
     * [payload] must be the RTP payload AFTER the 12-byte RTP header
     * (i.e. starting at the 8-byte main JPEG header). [marker] is the RTP
     * marker bit (last fragment of the frame).
     */
    fun feed(payload: ByteArray, marker: Boolean) {
        if (payload.size < 8) return
        val offset = ((payload[1].toInt() and 0xFF) shl 16) or
            ((payload[2].toInt() and 0xFF) shl 8) or
            (payload[3].toInt() and 0xFF)
        val type = payload[4].toInt() and 0xFF
        val q = payload[5].toInt() and 0xFF
        var pos = 8

        // The Restart Marker header (4 bytes: Restart Interval(16) |
        // F(1) | L(1) | Restart Count(14)) rides on EVERY fragment when the
        // Type field has bit 0x40 set — not just the first (FFmpeg
        // rtpdec_jpeg.c consumes it for every packet). Leaking it into the
        // scan inserts a 4-byte marker at each fragment boundary and breaks
        // the entropy stream.
        if ((type and 0x40) != 0) {
            if (payload.size - pos < 4) return
            pos += 4
        }

        if (offset == 0) {
            // A new frame begins. Any partial previous frame is discarded.
            frameBuf = ByteArray(0)
            written = 0
            header = null
            sawStart = true

            var firstLuma = -1
            when {
                q >= 128 -> {
                    // Quantization Table header + table data (we only need the
                    // first luma quantizer to pick the matching vendor header).
                    if (payload.size - pos < 4) return
                    val qlen = ((payload[pos + 2].toInt() and 0xFF) shl 8) or
                        (payload[pos + 3].toInt() and 0xFF)
                    pos += 4
                    if (qlen == 0) {
                        // Q=255 + Length=0 is invalid; other Q>=128 values must
                        // reference out-of-band tables we don't track — drop.
                        return
                    }
                    if (qlen % 64 != 0 || qlen > 256 || payload.size - pos < qlen) return
                    firstLuma = payload[pos].toInt() and 0xFF
                    pos += qlen
                }
                q in 1..99 -> {
                    // Q in 1..99: no in-band table, use Q directly.
                    firstLuma = -1
                }
                else -> return // q == 0 or q > 99 is reserved/invalid
            }

            val hdr = pickVendorHeader(q, firstLuma) ?: return
            header = hdr
        } else if (!sawStart) {
            // No start packet seen: can't build headers — discard the frame.
            return
        }

        val frag = payload.copyOfRange(pos, payload.size)
        val end = offset + frag.size
        if (end > frameBuf.size) {
            frameBuf = frameBuf.copyOf(end)
        }
        frag.copyInto(frameBuf, offset)
        if (end > written) written = end

        if (marker && sawStart) {
            val hdr = header ?: return
            var frame = ByteArray(hdr.size + written)
            hdr.copyInto(frame, 0)
            frameBuf.copyInto(frame, hdr.size, 0, written)
            // The camera's scans may end implicitly; ensure an explicit EOI.
            if (frame.size < 2 || frame[frame.size - 2] != 0xFF.toByte() || frame[frame.size - 1] != 0xD9.toByte()) {
                frame = frame + byteArrayOf(0xFF.toByte(), 0xD9.toByte())
            }
            frames++
            onFrame(frame)
            frameBuf = ByteArray(0)
            written = 0
            header = null
            sawStart = false
        }
    }

    // ------------------------------------------------------------- JPEG header

    /**
     * Pick the vendor header template whose quality is closest to the stream's.
     * [q] is the RTP Q field (255 => in-band tables, [firstLuma] is the first
     * luma quantizer from those tables); [firstLuma] == -1 for Q in 1..99.
     */
    private fun pickVendorHeader(q: Int, firstLuma: Int): ByteArray? {
        val nominal = if (q in 1..99) {
            q
        } else {
            // Map the in-band luma table's first quantizer to a nominal Q
            // (the vendor's six template tables start at these values).
            when {
                firstLuma < 0 -> return null
                firstLuma >= 0x80 -> 5
                firstLuma >= 0x40 -> 10
                firstLuma >= 0x18 -> 25
                firstLuma >= 0x0c -> 50
                firstLuma >= 0x04 -> 75
                else -> 100
            }
        }
        val levels = intArrayOf(5, 10, 25, 50, 75, 100)
        var best = 0
        var bestDist = Int.MAX_VALUE
        for (i in levels.indices) {
            val d = kotlin.math.abs(nominal - levels[i])
            if (d < bestDist) {
                bestDist = d
                best = i
            }
        }
        return when (best) {
            0 -> VENDOR_Q5_HEADER
            1 -> VENDOR_Q10_HEADER
            2 -> VENDOR_Q25_HEADER
            3 -> VENDOR_Q50_HEADER
            4 -> VENDOR_Q75_HEADER
            else -> VENDOR_Q100_HEADER
        }
    }

